(function(){
  var SKELETON_IMG = "data:image/jpeg;base64,";
  var ORGANS_IMG = "data:image/jpeg;base64,";

  var BONES = [
    { label: "1",  correct: "Skull (Cranium)",         fact: "Your skull is like a helmet — it protects your brain!" },
    { label: "2",  correct: "Collarbone (Clavicle)",   fact: "Your collarbone goes across the top of your chest, like a little hanger for your arms." },
    { label: "3",  correct: "Upper arm bone (Humerus)",fact: "The upper arm bone is the biggest bone between your shoulder and your elbow." },
    { label: "4",  correct: "Forearm bone (Ulna)",     fact: "The ulna is the forearm bone that lines up with your pinky finger." },
    { label: "5",  correct: "Forearm bone (Radius)",   fact: "The radius is the forearm bone that lines up with your thumb — it lets your palm turn up and down!" },
    { label: "6",  correct: "Thigh bone (Femur)",      fact: "The thigh bone is the longest, strongest bone in your whole body!" },
    { label: "7",  correct: "Shin bone (Tibia)",       fact: "The shin bone is the big bone in the front of your lower leg." },
    { label: "8",  correct: "Jawbone (Mandible)",      fact: "Your jawbone is the only bone in your head that can move — it helps you chew and talk!" },
    { label: "9",  correct: "Breastbone (Sternum)",    fact: "The breastbone is a flat bone in the middle of your chest — your ribs connect to it." },
    { label: "10", correct: "Ribs",                    fact: "Your ribs curve around your chest to protect your heart and lungs." },
    { label: "11", correct: "Hip bone (Ilium)",        fact: "The ilium is the wide, curvy part of your hip bone — you can feel it if you put your hands on your hips!" },
    { label: "12", correct: "Tailbone (Sacrum)",       fact: "At the very bottom of your spine is a bone that helps connect your backbone to your hips." },
    { label: "13", correct: "Hip bone (Pubis)",        fact: "The pubis is the front part of your hip bone, where the left and right sides of your pelvis meet." },
    { label: "14", correct: "Kneecap (Patella)",       fact: "Your kneecap is the small round bone that protects the front of your knee." },
    { label: "15", correct: "Calf bone (Fibula)",      fact: "The fibula is the thinner bone next to your shin bone, running down the outside of your lower leg." },
    { label: "16", correct: "Foot bones",              fact: "Each foot has 26 tiny bones working together to help you balance, walk, and run!" },
    { label: "17", correct: "Backbone (Spine)",        fact: "Your backbone is a stack of small bones called vertebrae — they protect your spinal cord and let you bend and twist." }
  ];

  var ORGANS = [
    { label: "A", correct: "Brain",              fact: "Your brain controls everything your body does — thinking, moving, even dreaming!" },
    { label: "B", correct: "Liver",              fact: "Your liver cleans your blood and helps break down the food you eat." },
    { label: "C", correct: "Gallbladder",        fact: "The gallbladder stores a liquid called bile that helps digest fatty foods." },
    { label: "D", correct: "Pancreas",           fact: "The pancreas helps break down food and controls the sugar in your blood." },
    { label: "E", correct: "Small intestine",    fact: "Food gets broken down even more in your small intestine so your body can use it." },
    { label: "F", correct: "Bladder",            fact: "Your bladder stores urine until your body is ready to let it go." },
    { label: "G", correct: "Lungs",              fact: "Your lungs fill up with air every time you breathe in oxygen." },
    { label: "H", correct: "Heart",              fact: "Your heart pumps blood all around your body, all day and all night!" },
    { label: "I", correct: "Stomach",            fact: "Your stomach mixes and mashes up the food you eat to help digest it." },
    { label: "J", correct: "Spleen",             fact: "Your spleen helps clean your blood and fights germs." },
    { label: "K", correct: "Kidneys",            fact: "Your kidneys filter your blood and make urine to remove waste." },
    { label: "L", correct: "Large intestine",    fact: "The large intestine absorbs water from digested food before it leaves your body." }
  ];

  var ROUND_SIZE = 8;

  function shuffle(arr){
    var a = arr.slice();
    for (var i = a.length - 1; i > 0; i--){
      var j = Math.floor(Math.random() * (i + 1));
      var t = a[i]; a[i] = a[j]; a[j] = t;
    }
    return a;
  }

  function pickChoices(correct, namesPool){
    var others = shuffle(namesPool.filter(function(n){ return n !== correct; })).slice(0, 3);
    return shuffle(others.concat([correct]));
  }

  function newRound(pool){
    return shuffle(pool.map(function(q, i){ return i; })).slice(0, ROUND_SIZE);
  }

  function start(host, ctx){

    function runQuiz(opts, onDone){
      var namesPool = opts.pool.map(function(q){ return q.correct; });
      var order = newRound(opts.pool);
      var idx = 0;
      var correct = 0;

      function render(){
        if (idx >= order.length){
          onDone(correct, order.length);
          return;
        }
        var q = opts.pool[order[idx]];
        var choices = pickChoices(q.correct, namesPool);

        host.innerHTML =
          '<div class="center">' +
            '<div class="h2">' + opts.title + '</div>' +
            '<div class="sub">' + opts.intro + '</div>' +
          '</div>' +
          '<div class="row center mt">' +
            '<img src="' + opts.imageSrc + '" alt="' + opts.imageAlt + '" style="max-width:' + opts.imgMaxWidth + ';width:100%;border-radius:12px;" />' +
          '</div>' +
          '<div class="center mt">' +
            '<div class="sub">Question ' + (idx + 1) + ' of ' + order.length + '</div>' +
            '<div class="h3">' + opts.questionText(q) + '</div>' +
          '</div>' +
          '<div class="story-grid mt" id="choices">' +
            choices.map(function(c){
              return '<button class="q-opt" data-answer="' + c.replace(/"/g,'&quot;') + '">' + c + '</button>';
            }).join('') +
          '</div>' +
          '<div class="fb center mt" id="fb" style="min-height:1.5em;"></div>';

        var btns = host.querySelectorAll('#choices .q-opt');
        btns.forEach(function(btn){
          btn.addEventListener('pointerup', function(){
            handleAnswer(btn, q, btns);
          });
        });
      }

      function handleAnswer(btn, q, allBtns){
        var chosen = btn.getAttribute('data-answer');
        var fb = host.querySelector('#fb');
        if (chosen === q.correct){
          btn.classList.add('correct');
          allBtns.forEach(function(b){ b.disabled = true; });
          if (!btn.dataset.wrongTried){
            correct++;
          }
          fb.className = 'fb ok center mt';
          fb.innerHTML = opts.correctPrefix(q) + ' ' + q.fact;
          if (ctx.toast) ctx.toast('Nice job!');
          var nextBtn = document.createElement('button');
          nextBtn.className = 'btn teal mt';
          nextBtn.textContent = (idx + 1 < order.length) ? 'Next →' : 'See Results →';
          nextBtn.addEventListener('pointerup', function(){
            idx++;
            render();
          });
          fb.appendChild(document.createElement('br'));
          fb.appendChild(nextBtn);
        } else {
          btn.disabled = true;
          btn.dataset.wrongTried = '1';
          fb.className = 'fb no center mt';
          fb.textContent = 'Not quite — try another one!';
        }
      }

      render();
    }

    function showMenu(){
      host.innerHTML =
        '<div class="center">' +
          '<img src="' + ctx.clover.head + '" alt="Clover" style="width:120px;" />' +
          '<div class="h2 mt">Clover\'s Check-Up</div>' +
          '<div class="sub mt">Clover twisted an ankle at soccer practice and is visiting Dr. Patel! ' +
          'Pick a challenge to help out.</div>' +
          '<div class="row center mt">' +
            '<button class="btn green" id="playBones">🦴 Bones</button>' +
            '<button class="btn teal" id="playOrgans">🫀 Organs</button>' +
          '</div>' +
          '<div class="row center mt">' +
            '<button class="btn ghost" id="done">← Map</button>' +
          '</div>' +
        '</div>';

      host.querySelector('#playBones').addEventListener('pointerup', playBones);
      host.querySelector('#playOrgans').addEventListener('pointerup', playOrgans);
      host.querySelector('#done').addEventListener('pointerup', function(){
        ctx.close();
      });
    }

    function playBones(){
      runQuiz({
        pool: BONES,
        title: "Clover's X-ray Check-Up — Bones",
        intro: "Dr. Patel needs your help reading the X-ray so Clover gets the right care. " +
          "Can you name the bones?",
        imageSrc: SKELETON_IMG,
        imageAlt: "Labeled skeleton",
        imgMaxWidth: "260px",
        questionText: function(q){ return 'Look at the skeleton picture above. Which bone is number ' + q.label + '?'; },
        correctPrefix: function(q){ return 'That\'s right! Number ' + q.label + ' is the ' + q.correct.toLowerCase() + '.'; }
      }, function(correct, total){
        renderLevelSummary('bones', 'Bones', correct, total, playBones);
      });
    }

    function playOrgans(){
      runQuiz({
        pool: ORGANS,
        title: "Clover's Check-Up — Organs",
        intro: "Dr. Patel needs help naming the organs that keep Clover healthy and strong. " +
          "Can you match each letter to the right organ?",
        imageSrc: ORGANS_IMG,
        imageAlt: "Labeled diagram of human organs",
        imgMaxWidth: "380px",
        questionText: function(q){ return 'Look at the diagram above. Which organ is labeled ' + q.label + '?'; },
        correctPrefix: function(q){ return 'That\'s right! Letter ' + q.label + ' is the ' + q.correct.toLowerCase() + '.'; }
      }, function(correct, total){
        renderLevelSummary('organs', 'Organs', correct, total, playOrgans);
      });
    }

    function renderLevelSummary(key, levelName, correct, total, replayFn){
      var star = correct >= 6;
      var coins = correct;
      var flagName = 'hospital' + key.charAt(0).toUpperCase() + key.slice(1) + 'StarEarned';

      if (!ctx.state[flagName]){
        ctx.state[flagName] = true;
        ctx.award({ coins: coins, star: star });
        if (ctx.confetti && star) ctx.confetti();
      }

      var cloverImg = star ? ctx.clover.cele : ctx.clover.head;
      var msg = star
        ? 'Great work! Dr. Patel says you\'d make a great doctor.'
        : 'Nice try! Come back and visit the hospital again anytime.';

      host.innerHTML =
        '<div class="center">' +
          '<img src="' + cloverImg + '" alt="Clover" style="width:120px;" />' +
          '<div class="h2 mt">' + levelName + ': ' + correct + ' / ' + total + ' correct!</div>' +
          '<div class="sub mt">' + msg + '</div>' +
          (star ? '<div class="sub mt">⭐ You earned a star!</div>' : '') +
          '<div class="row center mt">' +
            '<button class="btn green" id="again">Play Again</button>' +
            '<button class="btn teal" id="menu">← Menu</button>' +
          '</div>' +
        '</div>';

      host.querySelector('#again').addEventListener('pointerup', replayFn);
      host.querySelector('#menu').addEventListener('pointerup', showMenu);
    }

    showMenu();
  }

  window.Stops.register('5A', { name: 'Hospital', start: start });
})();
